import datetimeimport jsonimport discordimport asyncioimport urllib3.utilfrom discord import Colorfrom discord.ext import commandsfrom discord.utils import utcnowfrom requests.compat import integer_typesfrom cogs.JoinCommand import JoinCommandfrom cogs.LeaveCommand import LeaveCommandfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.GetMP3DurationUtility import GeMP3DurationUtilityclass PlayDownloadedSongButtonView(discord.ui.View):    def __init__(self, ctx: discord.ext.commands.Context, bot: commands.Bot, file: str, file_info: str,                 url: urllib3.util.Url = None):        self.ctx = ctx        self.bot = bot        self.file = file        self.file_info = file_info        self.url = url        self.data = None        super().__init__(timeout=None)    # noinspection PyTypeChecker    @discord.ui.button(label="Play This Song In My Voice Channel!", custom_id="button-2",                       style=discord.ButtonStyle.primary, emoji="▶️")    async def button_callback(self, interaction: discord.Interaction, button: discord.ui.Button):        if await JoinCommand.join(JoinCommand(self.bot), self.ctx):            button.disabled = True            await interaction.response.edit_message(view=self)            voice_client = discord.utils.get(self.bot.voice_clients, guild=interaction.guild)            duration_seconds = GeMP3DurationUtility.get_mp3_duration(file_path=self.file)            if voice_client and voice_client.is_connected():                if voice_client.is_playing():                    voice_client.stop_playing()                ffmpeg_options = {                    'options': '-b:a 192k -loglevel quiet',                }                source = discord.FFmpegPCMAudio(source=self.file,                                                executable=self.bot.ffmpeg, **ffmpeg_options)                with open(self.file_info, 'r') as info_file:                    data = json.load(info_file)                    self.data = data                    await self.bot.change_presence(                        activity=discord.Activity(type=discord.ActivityType.streaming, name=data['title'],                                                  url=self.url))                embed1 = discord.Embed(title=f"▶️ Playing Song: {data['title']}", description=data['description'],                                       colour=Color.magenta(), timestamp=utcnow())                embed1.set_footer(                    text=f"This message was brought to you by {self.bot.user.name}'s Message Delivery System!",                    icon_url=self.bot.user.avatar.url)                embed1.set_image(url=data['thumbnail'])                embed1.add_field(name="Title / Artist", value=data['title'])                embed1.add_field(name="Video ID", value=data['id'])                embed1.add_field(name="Channel", value=data['channel_url'])                embed1.add_field(name="Video Duration", value=data['duration_string'])                embed1.add_field(name="Like Count", value=data['like_count'])                embed1.add_field(name="View Count", value=data['view_count'])                await interaction.followup.send(embed=embed1)                voice_client.play(source, after=lambda e: print(f"Player error: {e}") if e else None)                while interaction.guild.voice_client.is_playing():                    await asyncio.sleep(duration_seconds + 1)                embed2 = EmbedGenerator.generate_simple_message_embed(description=f"Finished Speaking!",                                                                      colour=Color.green(), timestamp=False)                await interaction.followup.send(embed=embed2)                await self.bot.change_presence(activity=None)                await LeaveCommand.leave(LeaveCommand(self.bot), self.ctx)            else:                await interaction.response.edit_message(view=self)# noinspection PyTypeCheckerasync def setup(bot: commands.Bot):    bot.add_view(PlayDownloadedSongButtonView(bot=bot, ctx=None, file=None, file_info=None))